void Absorp::disableAbs()
{
    abs1->setEnabled(false);
    abs2->setEnabled(false);
    abs3->setEnabled(false);
    abs4->setEnabled(false);
    abs5->setEnabled(false);
    abs6->setEnabled(false);
    abs7->setEnabled(false);
    abs8->setEnabled(false);
    Absorption_window_button->setEnabled(false);
    scaleDown->setEnabled(false);
    scaleUp->setEnabled(false);
}

void Absorp::enableAbs()
{
    abs1->setEnabled(true);
    abs2->setEnabled(true);
    abs3->setEnabled(true);
    abs4->setEnabled(true);
    abs5->setEnabled(true);
    abs6->setEnabled(true);
    abs7->setEnabled(true);
    abs8->setEnabled(true);
    Absorption_window_button->setEnabled(true);
    scaleDown->setEnabled(true);
    scaleUp->setEnabled(true);
}

void Absorp::setAllAbsorptionToTarget(float newValue)
{
    parent->hidePickerWindow();
    pickerCoords.setXY(-1, -1);
    for (int i = 0; i < Parameters::NUM_FREQ; i++)
    {
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->beginChangeGesture();
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->setValueNotifyingHost(newValue);
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->endChangeGesture();
    }
}

void Absorp::setAbsorptionToPreset(int preset)
{
    parent->setPickerToPreset(this, preset, &pickerCoords);
    for (int i = 0; i < Parameters::NUM_FREQ; i++)
    {
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->beginChangeGesture();
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->setValueNotifyingHost(FilterPresets::PRESETS_VALUES[preset][i]);
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->endChangeGesture();
    }
}

void Absorp::scaleAbsorption(float scale)
{
    parent->hidePickerWindow();
    pickerCoords.setXY(-1, -1);
    for (int i = 0; i < Parameters::NUM_FREQ; i++)
    {
        float scaledValue = valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->getValue() + scale;
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->beginChangeGesture();
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->setValueNotifyingHost(scaledValue);
        valueTreeState.getParameter(String("freq") + String(wallID) + String(i))->endChangeGesture();
    }
}

